'use strict';
const $ = s => document.querySelector(s), key = 'last-shift-editor-v1';
const uid = () => globalThis.crypto?.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
const blank = () => ({version:1,sections:[],characters:[],backgrounds:[]});
let data=blank(),sectionId='',chapterId='',sceneId='',assetKind='',assetId='',draftAsset=null,loadFailed=false;
function normalize(d){if(!d||d.version!==1||!Array.isArray(d.sections)||!Array.isArray(d.characters)||!d.sections.every(s=>Array.isArray(s.chapters)&&s.chapters.every(c=>Array.isArray(c.scenes)&&c.scenes.every(s=>Array.isArray(s.choices)))))throw Error('invalid');d.backgrounds=Array.isArray(d.backgrounds)?d.backgrounds:[];d.characters.forEach(c=>{if(!Array.isArray(c.emotions))c.emotions=c.image?[{id:uid(),name:'Обычный',image:c.image}]:[]});d.sections.forEach(s=>s.chapters.forEach(c=>c.scenes.forEach(sc=>{if(sc.image&&!sc.backgroundId){let bg=d.backgrounds.find(b=>b.image===sc.image);if(!bg){bg={id:uid(),name:`Фон: ${sc.name||'сцена'}`,image:sc.image};d.backgrounds.push(bg)}sc.backgroundId=bg.id}if(!sc.emotionId&&sc.characterId){const person=d.characters.find(p=>p.id===sc.characterId);sc.emotionId=person?.emotions[0]?.id||''}sc.backgroundId ||= '';sc.characterId ||= '';sc.emotionId ||= '';sc.text ||= '';sc.choices.forEach(ch=>{ch.nextSceneId ||= '';ch.characterId ||= '';ch.money=Number(ch.money)||0;ch.relationship=Number(ch.relationship)||0})})));return d}
let db=null,fileHandle=null,saveTimer=null,revision=0,fileRevision=0,writeQueue=Promise.resolve();
const section=()=>data.sections.find(x=>x.id===sectionId), chapter=()=>section()?.chapters.find(x=>x.id===chapterId), scene=()=>chapter()?.scenes.find(x=>x.id===sceneId), character=id=>data.characters.find(x=>x.id===id), background=id=>data.backgrounds.find(x=>x.id===id);
function dbOpen(){return new Promise((resolve,reject)=>{const req=indexedDB.open('last-shift-editor',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('База данных заблокирована другой вкладкой'));});}
function dbGet(){return new Promise((resolve,reject)=>{const tx=db.transaction('projects','readonly'),req=tx.objectStore('projects').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbPut(snapshot){return new Promise((resolve,reject)=>{const tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(snapshot,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Сохранение отменено'));});}
function queueSave(){const snapshot=structuredClone(data), current=revision;writeQueue=writeQueue.catch(()=>{}).then(async()=>{await dbPut(snapshot);if(fileHandle){try{const writable=await fileHandle.createWritable();await writable.write(JSON.stringify(snapshot,null,2));await writable.close();fileRevision=current}catch(e){fileHandle=null;$('#file-button').textContent='Подключить файл';$('#save-status').textContent='В браузере сохранено; файл отключён';alert('Не удалось записать файл. Изменения сохранены в браузере. Подключите файл заново или экспортируйте проект.');return}}if(current===revision)$('#save-status').textContent=fileHandle?'Сохранено в файл и браузер':'Сохранено в браузере';}).catch(e=>{$('#save-status').textContent='Ошибка сохранения — экспортируйте';console.error(e);alert('Не удалось сохранить проект. Экспортируйте его в файл, чтобы не потерять изменения.');});return writeQueue}
function save(){if(loadFailed){$('#save-status').textContent='Сохранение отключено';return false}revision++;$('#save-status').textContent='Сохранение…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveTimer=null;queueSave()},500);return true}
async function init(){try{db=await dbOpen();const stored=await dbGet();if(stored)data=normalize(stored);else {const old=localStorage.getItem(key);if(old){data=normalize(JSON.parse(old));await dbPut(structuredClone(data));}}navigator.storage?.persist?.().catch(()=>{});$('#save-status').textContent='Сохранено в браузере';}catch(e){loadFailed=true;$('#save-status').textContent='Сохранение недоступно';console.error(e);alert('Не удалось открыть хранилище проекта. Сохранение отключено, чтобы не перезаписать данные. Попробуйте другой браузер или восстановите резервную копию.')}renderSelectors();$('#loading-overlay').remove()}
$('#file-button').onclick=async()=>{if(!window.showSaveFilePicker){alert('Этот браузер не поддерживает автоматическую запись в выбранный файл. Используйте Chrome или Edge и откройте редактор через localhost или HTTPS. Кнопка «Экспорт» доступна в любом браузере.');return}try{const handle=await window.showSaveFilePicker({suggestedName:'poslednyaya-smena-project.json',types:[{description:'Проект игры',accept:{'application/json':['.json']}}]});fileHandle=handle;$('#file-button').textContent='Файл: '+handle.name;revision++;clearTimeout(saveTimer);saveTimer=null;await queueSave()}catch(e){if(e.name!=='AbortError')alert('Не удалось подключить файл: '+e.message)}};
window.addEventListener('beforeunload',e=>{if(saveTimer){clearTimeout(saveTimer);saveTimer=null;queueSave();}if(fileHandle&&fileRevision<revision){e.preventDefault();e.returnValue='';}});
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!=null)n.textContent=text;return n}
function button(text,fn,cls='button subtle'){const n=el('button',cls,text);n.type='button';n.onclick=fn;return n}
function options(select,entries,value){select.replaceChildren();entries.forEach(([v,t])=>{const o=el('option','',t);o.value=v;select.append(o)});select.value=value||''}
function empty(node,title,desc){node.replaceChildren();const box=el('div','empty');box.append(el('strong','',title),document.createTextNode(desc));node.append(box)}
function image(src){if(!src)return el('div','list-image asset-placeholder','▧');const i=el('img','list-image');i.src=src;i.alt='';return i}
function show(tab){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==`${tab}-view`);document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.tab===tab));if(tab==='characters')renderCharacters();if(tab==='backgrounds')renderBackgrounds();if(tab==='chapter')renderEditor()}
function renderSelectors(){if(!section())sectionId=data.sections[0]?.id||'';if(!chapter())chapterId=section()?.chapters[0]?.id||'';if(!scene())sceneId=chapter()?.scenes[0]?.id||'';options($('#current-section'),[['','Выберите раздел'],...data.sections.map(s=>[s.id,s.name])],sectionId);options($('#current-chapter'),[['','Выберите главу'],...(section()?.chapters||[]).map(c=>[c.id,c.name])],chapterId);$('#current-chapter').disabled=!section();$('#new-chapter').disabled=!section();$('#edit-settings').disabled=!section();renderEditor()}
$('#current-section').onchange=e=>{sectionId=e.target.value;chapterId='';sceneId='';renderSelectors()};$('#current-chapter').onchange=e=>{chapterId=e.target.value;sceneId='';renderSelectors()};
$('#new-section').onclick=()=>{const name=prompt('Название нового раздела:');if(!name?.trim())return;const s={id:uid(),name:name.trim(),description:'',status:'draft',image:'',chapters:[]};data.sections.push(s);sectionId=s.id;chapterId='';sceneId='';save();renderSelectors();show('chapter')};
$('#new-chapter').onclick=()=>{if(!section())return;const name=prompt('Название новой главы:');if(!name?.trim())return;const c={id:uid(),name:name.trim(),description:'',status:'draft',image:'',scenes:[]};section().chapters.push(c);chapterId=c.id;sceneId='';save();renderSelectors();show('chapter')};
function renderEditor(){const c=chapter();$('#chapter-empty').hidden=!!c;$('#editor-workspace').hidden=!c;$('#add-scene').disabled=!c;$('#chapter-context').textContent=c?`${section().name} / ${c.name}`:'Выберите раздел и главу сверху.';if(!c)return;renderSceneList();renderMap();renderScene()}
function renderSceneList(){const list=$('#scene-list');list.replaceChildren();chapter().scenes.forEach((s,i)=>{const row=el('div','scene-item'+(s.id===sceneId?' active':''));const select=button(`${String(i+1).padStart(2,'0')}   ${s.name||'Без названия'}`,()=>{sceneId=s.id;renderEditor()},'map-select');select.style.cssText='border:0;background:none;text-align:left;flex:1;color:inherit;font:inherit';const tools=el('span','scene-tools');const up=button('↑',()=>moveScene(i,-1),'');const down=button('↓',()=>moveScene(i,1),'');up.title='Переместить вверх';down.title='Переместить вниз';up.disabled=i===0;down.disabled=i===chapter().scenes.length-1;tools.append(up,down);row.append(select,el('small','',i===0?'НАЧАЛО':''),tools);list.append(row)});if(!chapter().scenes.length)empty(list,'Сцен пока нет','Создайте первую сцену.')}
function moveScene(i,delta){const arr=chapter().scenes;[arr[i],arr[i+delta]]=[arr[i+delta],arr[i]];save();renderEditor()}
function renderMap(){
 const map=$('#story-map'),scenes=chapter().scenes;map.replaceChildren();
 if(!scenes.length){map.append(el('p','help','Здесь появятся переходы между сценами.'));return}
 const width=520,rowHeight=105,nodeWidth=310,nodeHeight=62,left=65,height=Math.max(160,scenes.length*rowHeight+60);
 const canvas=el('div','diagram-canvas');canvas.style.width=width+'px';canvas.style.height=height+'px';
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('aria-hidden','true');svg.classList.add('diagram-arrows');
 const defs=document.createElementNS(ns,'defs'),marker=document.createElementNS(ns,'marker');marker.setAttribute('id','arrow-head');marker.setAttribute('viewBox','0 0 10 10');marker.setAttribute('refX','9');marker.setAttribute('refY','5');marker.setAttribute('markerWidth','6');marker.setAttribute('markerHeight','6');marker.setAttribute('orient','auto-start-reverse');const head=document.createElementNS(ns,'path');head.setAttribute('d','M 0 0 L 10 5 L 0 10 z');head.setAttribute('fill','#75aec8');marker.append(head);defs.append(marker);svg.append(defs);
 scenes.forEach((s,i)=>{const y=24+i*rowHeight;s.choices.forEach((ch,j)=>{const target=scenes.findIndex(x=>x.id===ch.nextSceneId);if(target<0)return;const destY=24+target*rowHeight;const lane=400+Math.min(j,4)*18;const sy=y+nodeHeight/2,ty=destY+nodeHeight/2;const path=document.createElementNS(ns,'path');path.setAttribute('d',`M ${left+nodeWidth} ${sy} C ${lane} ${sy}, ${lane} ${ty}, ${left+nodeWidth} ${ty}`);if(target===i)path.setAttribute('d',`M ${left+nodeWidth} ${sy-10} C ${lane+45} ${sy-55}, ${lane+45} ${sy+55}, ${left+nodeWidth} ${sy+10}`);path.setAttribute('class','diagram-line');path.setAttribute('marker-end','url(#arrow-head)');svg.append(path)})});canvas.append(svg);
 scenes.forEach((s,i)=>{const node=button('',()=>{sceneId=s.id;renderEditor()},'diagram-node'+(s.id===sceneId?' active':''));node.style.left=left+'px';node.style.top=(24+i*rowHeight)+'px';node.style.width=nodeWidth+'px';node.style.height=nodeHeight+'px';node.append(el('span','diagram-index',i===0?'СТАРТ':String(i+1).padStart(2,'0')),el('strong','',s.name||'Без названия'));const details=el('span','diagram-detail');details.textContent=s.choices.length?s.choices.map(ch=>{const dest=scenes.find(x=>x.id===ch.nextSceneId);return `${ch.text||'Выбор'} → ${dest?.name||(ch.nextSceneId?'нет сцены':'конец')}`}).join(' · '):'Конец главы';node.append(details);node.title=details.textContent;canvas.append(node)});map.append(canvas)
}
function renderScene(){const s=scene();$('#scene-empty').hidden=!!s;$('#scene-editor').hidden=!s;if(!s)return;$('#scene-heading').textContent=s.name||'Без названия';$('#scene-name').value=s.name;$('#scene-text').value=s.text;options($('#scene-background'),[['','Без фона'],...data.backgrounds.map(x=>[x.id,x.name])],s.backgroundId);options($('#scene-character'),[['','Повествование без персонажа'],...data.characters.map(x=>[x.id,x.name])],s.characterId);renderEmotionsSelect();renderChoices();renderLive()}
function renderEmotionsSelect(){const s=scene(),p=character(s.characterId);options($('#scene-emotion'),[['','Без изображения'],...(p?.emotions||[]).map(x=>[x.id,x.name])],s.emotionId);$('#scene-emotion').disabled=!p||!p.emotions.length}
function makePhone(s,onChoice){
 const person=character(s.characterId),emotion=person?.emotions.find(x=>x.id===s.emotionId),bg=background(s.backgroundId),phone=el('div','phone-frame'),stage=el('div','live-stage'+(!person?' narration':''));
 if(bg?.image)stage.style.backgroundImage=`url(${JSON.stringify(bg.image)})`;
 if(emotion?.image){const img=el('img','live-character');img.src=emotion.image;img.alt=person.name;stage.append(img)}
 const content=el('div','phone-content'),dialog=el('div','live-dialogue');if(person)dialog.append(el('strong','speaker',person.name));dialog.append(el('p','',s.text||'Здесь появится текст сцены.'));content.append(dialog);
 if(s.choices.length){const choices=el('div','live-choices');s.choices.forEach(c=>{const choice=onChoice?button(c.text||'Текст выбора',()=>onChoice(c),'phone-choice'):el('div','phone-choice',c.text||'Текст выбора');choices.append(choice)});content.append(choices)}stage.append(content);phone.append(stage);return phone
}
function renderLive(){const root=$('#live-preview');root.replaceChildren(makePhone(scene()))}
function field(title,type,value,change,placeholder='',number=false){const l=el('label','',title),input=el(type);if(type==='input'){input.type=number?'number':'text';input.placeholder=placeholder}input.value=value;input.addEventListener(type==='select'?'change':'input',()=>{change(input.value);save();renderLive();renderMap()});l.append(input);return l}
function renderChoices(){const list=$('#choice-list');list.replaceChildren();const s=scene();if(!s.choices.length){empty(list,'Выборов пока нет','Без выборов эта сцена завершает главу.');return}s.choices.forEach((ch,i)=>{const card=el('div','choice-card'),top=el('div','choice-top');top.append(el('strong','',`Выбор ${i+1}`),button('Удалить',()=>{if(confirm('Удалить выбор?')){s.choices.splice(i,1);save();renderChoices();renderMap();renderLive()}},'button danger'));card.append(top);card.append(field('Текст, который увидит игрок','input',ch.text,v=>ch.text=v,'Например, помочь'));const target=field('Переход к сцене','select',ch.nextSceneId,v=>ch.nextSceneId=v);options(target.querySelector('select'),[['','Конец главы'],...chapter().scenes.map(x=>[x.id,x.name])],ch.nextSceneId);card.append(target);const row=el('div','effect-row');const money=field('Баланс: изменение','input',ch.money,v=>ch.money=Number(v)||0,'0',true),person=field('Отношения с','select',ch.characterId,v=>ch.characterId=v),rel=field('Отношения: изменение','input',ch.relationship,v=>ch.relationship=Number(v)||0,'0',true);options(person.querySelector('select'),[['','Без персонажа'],...data.characters.map(c=>[c.id,c.name])],ch.characterId);row.append(money,person,rel);card.append(row,el('p','help','Положительное число прибавляет, отрицательное — уменьшает. Последствия работают в предпросмотре.'));list.append(card)})}
$('#add-scene').onclick=()=>{const s={id:uid(),name:'Новая сцена',text:'',backgroundId:'',characterId:'',emotionId:'',choices:[]};chapter().scenes.push(s);sceneId=s.id;save();renderEditor()};$('#delete-scene').onclick=()=>{const refs=chapter().scenes.flatMap(s=>s.choices).filter(c=>c.nextSceneId===sceneId);if(confirm(`Удалить сцену? Переходов на неё: ${refs.length}. Они станут концом главы.`)){refs.forEach(c=>c.nextSceneId='');chapter().scenes=chapter().scenes.filter(s=>s.id!==sceneId);sceneId=chapter().scenes[0]?.id||'';save();renderEditor()}};
$('#scene-name').oninput=e=>{scene().name=e.target.value;$('#scene-heading').textContent=e.target.value||'Без названия';save();renderSceneList();renderMap()};$('#scene-text').oninput=e=>{scene().text=e.target.value;save();renderLive()};$('#scene-background').onchange=e=>{scene().backgroundId=e.target.value;save();renderLive()};$('#scene-character').onchange=e=>{scene().characterId=e.target.value;scene().emotionId=character(e.target.value)?.emotions[0]?.id||'';save();renderEmotionsSelect();renderLive()};$('#scene-emotion').onchange=e=>{scene().emotionId=e.target.value;save();renderLive()};$('#add-choice').onclick=()=>{scene().choices.push({id:uid(),text:'',nextSceneId:'',money:0,characterId:'',relationship:0});save();renderChoices();renderMap();renderLive()};
function readImage(file,callback){if(!file)return;if(!file.type.startsWith('image/'))return alert('Выберите изображение.');if(file.size>15*1024*1024)return alert('Выберите изображение до 15 МБ.');const r=new FileReader();r.onload=()=>callback(r.result);r.onerror=()=>alert('Не удалось прочитать изображение.');r.readAsDataURL(file)}
function renderLibrary(list,items,kind){list.replaceChildren();if(!items.length)return empty(list,kind==='character'?'Пока нет персонажей':'Пока нет фонов','Добавьте элемент в библиотеку.');items.forEach(a=>{const card=el('div','list-card'),body=el('div','list-content');const src=kind==='character'?a.emotions[0]?.image:a.image;body.append(el('strong','',a.name),el('p','',kind==='character'?`${a.emotions.length} образов · ${a.description||'Без описания'}`:'Фон сцены'));card.append(image(src),body,button('Изменить',()=>openAsset(kind,a.id)));list.append(card)})}
function renderCharacters(){renderLibrary($('#character-list'),data.characters,'character')}function renderBackgrounds(){renderLibrary($('#background-list'),data.backgrounds,'background')}
function openAsset(kind,id=''){assetKind=kind;assetId=id;const original=(kind==='character'?data.characters:data.backgrounds).find(x=>x.id===id);draftAsset=original?structuredClone(original):kind==='character'?{id:uid(),name:'',description:'',emotions:[]}:{id:uid(),name:'',image:''};$('#asset-title').textContent=kind==='character'?'Персонаж':'Фон сцены';$('#asset-type').textContent=id?'РЕДАКТИРОВАНИЕ':'НОВЫЙ ЭЛЕМЕНТ';$('#asset-name').value=draftAsset.name;$('#asset-description').value=draftAsset.description||'';$('#character-fields').hidden=kind!=='character';$('#background-fields').hidden=kind!=='background';$('#delete-asset').hidden=!id;$('#background-image').value='';renderAsset();$('#asset-dialog').showModal()}
function renderAsset(){if(assetKind==='background'){const img=$('#background-preview');img.hidden=!draftAsset.image;if(draftAsset.image)img.src=draftAsset.image;return}const list=$('#emotion-list');list.replaceChildren();draftAsset.emotions.forEach((e,i)=>{const row=el('div','emotion-row'),name=el('input');name.placeholder='Название образа';name.value=e.name;name.oninput=()=>e.name=name.value;const upload=el('input');upload.type='file';upload.accept='image/*';upload.onchange=()=>readImage(upload.files[0],src=>{e.image=src;renderAsset()});const tools=el('div');if(e.image){const img=el('img','emotion-thumb');img.src=e.image;img.alt='';tools.append(img)}tools.append(button('×',()=>{draftAsset.emotions.splice(i,1);renderAsset()},'close'));row.append(name,upload,tools);list.append(row)});if(!draftAsset.emotions.length)list.append(el('p','help','Добавьте хотя бы один образ и загрузите его изображение.'))}
$('#add-character').onclick=()=>openAsset('character');$('#add-background').onclick=()=>openAsset('background');$('#add-emotion').onclick=()=>{draftAsset.emotions.push({id:uid(),name:'Обычный',image:''});renderAsset()};$('#background-image').onchange=e=>readImage(e.target.files[0],src=>{draftAsset.image=src;renderAsset()});$('#remove-background-image').onclick=()=>{draftAsset.image='';renderAsset()};
$('#asset-form').onsubmit=e=>{e.preventDefault();draftAsset.name=$('#asset-name').value.trim();if(!draftAsset.name)return;draftAsset.description=$('#asset-description').value;const arr=assetKind==='character'?data.characters:data.backgrounds,index=arr.findIndex(x=>x.id===assetId);if(index<0)arr.push(draftAsset);else arr[index]=draftAsset;save();$('#asset-dialog').close();assetKind==='character'?renderCharacters():renderBackgrounds()};
$('#delete-asset').onclick=()=>{if(!confirm('Удалить из библиотеки? В сценах, где используется этот элемент, выбор будет очищен.'))return;data.sections.forEach(s=>s.chapters.forEach(c=>c.scenes.forEach(sc=>{if(assetKind==='character'&&sc.characterId===assetId){sc.characterId='';sc.emotionId=''}if(assetKind==='background'&&sc.backgroundId===assetId)sc.backgroundId='';sc.choices.forEach(ch=>{if(assetKind==='character'&&ch.characterId===assetId)ch.characterId=''})})));if(assetKind==='character')data.characters=data.characters.filter(x=>x.id!==assetId);else data.backgrounds=data.backgrounds.filter(x=>x.id!==assetId);save();$('#asset-dialog').close();assetKind==='character'?renderCharacters():renderBackgrounds()};
function settingsField(parent,labelText,obj,prop,kind='input'){const l=el('label','',labelText),input=el(kind);if(kind==='select')options(input,[['draft','Черновик'],['available','Доступно'],['locked','Недоступно']],obj[prop]);else input.value=obj[prop]||'';input.dataset.object=obj===section()?'section':'chapter';input.dataset.prop=prop;l.append(input);parent.append(l)}
