const oldMakePhone=makePhone;makePhone=function(s,onChoice,lineIndex=0){const line=lineIndex===0?s:(s.lines||[])[lineIndex-1];const current={...s,characterId:line.characterId,emotionId:line.emotionId,text:line.text};const total=1+(s.lines||[]).length;if(lineIndex<total-1)current.choices=[];const phone=oldMakePhone(current,onChoice);const stage=phone.querySelector('.live-stage'),frame=s.frame||{};stage.style.backgroundPosition=`${frame.bgX??50}% ${frame.bgY??50}%`;const img=stage.querySelector('.live-character');if(img){img.style.left=`${frame.x??50}%`;img.style.height=`${(frame.scale??100)*.82}%`}if(onChoice&&lineIndex<total-1){const content=phone.querySelector('.phone-content');content.append(button('Далее →',()=>onChoice({__nextLine:true}),'phone-choice'))}return phone};
