play=function(id,state,lineIndex=0,notices=[]){const root=$('#play-content');root.replaceChildren();const s=chapter().scenes.find(x=>x.id===id);if(!s){root.append(el('p','warning','Сцена не найдена. Проверьте переход.'));return}prepScene(s);const go=next=>{if(next)play(next,state,0,notices);else{root.replaceChildren(el('div','empty','Конец главы'),el('p','preview-stat',stats(state)),...(notices.length?[el('p','final-effects',notices.join(' · '))]:[]),button('Начать заново',()=>play(chapter().scenes[0].id,startState())));}};root.append(makePhone(s,c=>{if(c.__nextLine){play(id,state,lineIndex+1);return}const cost=Math.max(0,Number(c.cost)||0);if(state.money<cost)return;state.money-=cost;state.money+=Number(c.money)||0;if(c.statId)state.values[c.statId]=(state.values[c.statId]??0)+(Number(c.statChange)||0);notices=[];if(cost)notices.push(`Баланс −${cost}`);if(c.money)notices.push(`Баланс ${c.money>0?'+':''}${c.money}`);if(c.statId&&c.statChange)notices.push(`${statName(c.statId)} ${c.statChange>0?'+':''}${c.statChange}`);go(resolveRoute(c.condition,c.nextSceneId,state))},lineIndex,state));if(notices.length){const overlay=el('div','effect-toast',notices.join(' · '));root.querySelector('.live-stage').append(overlay);setTimeout(()=>overlay.remove(),2200)}if(lineIndex>=s.lines.length&&!s.choices.length){const next=resolveRoute(s.route,s.route.next,state);root.append(button(next?'Далее →':'Завершить главу',()=>go(next),'button subtle preview-choice'))}root.append(el('p','preview-stat',stats(state)))};
