function metricValue(id,state){return id.startsWith('rel:')?(state.relations[id.slice(4)]||0):(state.values[id]??0)}
function metricName(id){return id.startsWith('rel:')?`Отношения: ${character(id.slice(4))?.name||'персонаж'}`:statName(id)}
function meets(value,operator,threshold){return operator==='>'?value>threshold:operator==='>='?value>=threshold:operator==='<'?value<threshold:operator==='<='?value<=threshold:operator==='!='?value!==threshold:value===threshold}
