// Публикация создаёт отдельный снимок, черновики остаются в редакторе.
function publishedRead(){return new Promise((resolve,reject)=>{const tx=db.transaction('projects','readonly'),r=tx.objectStore('projects').get('published-catalog-v1');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
