function combinePublic(base,local){const out=structuredClone(base||{version:1,sections:[],characters:[],backgrounds:[],stats:[]});for(const kind of ['characters','backgrounds','stats']){const map=new Map((out[kind]||[]).map(x=>[x.id,x]));(local[kind]||[]).forEach(x=>map.set(x.id,x));out[kind]=[...map.values()]}const sections=new Map((out.sections||[]).map(x=>[x.id,x]));for(const s of local.sections||[]){const existing=sections.get(s.id);if(!existing)sections.set(s.id,s);else{const chapters=new Map((existing.chapters||[]).map(c=>[c.id,c]));(s.chapters||[]).forEach(c=>chapters.set(c.id,c));sections.set(s.id,{...existing,...s,chapters:[...chapters.values()]})}}out.sections=[...sections.values()];return out}
function downloadPublic(value){const content='window.PUBLISHED_STORIES = '+JSON.stringify(value).replace(/</g,'\\u003c')+';\n',blob=new Blob([content],{type:'text/javascript'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='published-catalog.js';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#publish-chapter').onclick=async()=>{const sec=section(),ch=chapter();if(!sec||!ch)return alert('Сначала выберите раздел и главу.');if(!ch.scenes.length)return alert('Добавьте хотя бы одну сцену.');try{const old=await publishedRead()||{version:1,sections:[],characters:[],backgrounds:[],stats:[]};const characterIds=new Set(),backgroundIds=new Set(),statIds=new Set();for(const scene of ch.scenes){if(scene.characterId)characterIds.add(scene.characterId);if(scene.backgroundId)backgroundIds.add(scene.backgroundId);if(scene.route?.statId)statIds.add(scene.route.statId);for(const line of scene.lines||[])if(line.characterId)characterIds.add(line.characterId);for(const choice of scene.choices||[]){if(choice.statId)statIds.add(choice.statId);if(choice.condition?.statId)statIds.add(choice.condition.statId);if(choice.requirement?.statId)statIds.add(choice.requirement.statId)}}const update={version:1,sections:[{...structuredClone(sec),chapters:[structuredClone(ch)]}],characters:structuredClone(data.characters.filter(x=>characterIds.has(x.id))),backgrounds:structuredClone(data.backgrounds.filter(x=>backgroundIds.has(x.id))),stats:structuredClone(data.stats.filter(x=>statIds.has(x.id)))};const result=combinePublic(old,update);await publishedWrite(result);alert('Глава опубликована в этом браузере. Для пользователей GitHub Pages нажмите «Скачать для сайта» и загрузите полученный published-catalog.js в папку сайта.');}catch(e){console.error(e);alert('Не удалось опубликовать главу: '+e.message)}};
$('#download-catalog').onclick=async()=>{try{const local=await publishedRead();const result=combinePublic(window.PUBLISHED_STORIES,local);if(!result.sections.length)return alert('Сначала опубликуйте хотя бы одну главу.');downloadPublic(result)}catch(e){alert('Не удалось подготовить файл: '+e.message)}};
init();
